<script setup>
import { ref, computed, onMounted } from 'vue'; import { api, date, time } from '../api'; import Hero from '../components/Hero.vue'; import { CalendarDays, List, UserRound, MapPin, SlidersHorizontal } from 'lucide-vue-next'
const sessions = ref([]), busy=ref(false), error=ref(''), category=ref(''), teacher=ref(''), location=ref(''), calendar=ref(false)
const today = new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const from=ref(today), until=ref(new Date(Date.now()+30*86400000).toISOString().slice(0,10))
const categories=computed(()=>[...new Set(sessions.value.map(s=>s.category))]), teachers=computed(()=>[...new Set(sessions.value.map(s=>s.teacher))]), locations=computed(()=>[...new Set(sessions.value.map(s=>s.location))])
const filtered=computed(()=>sessions.value.filter(s=>(!category.value||s.category===category.value)&&(!teacher.value||s.teacher===teacher.value)&&(!location.value||s.location===location.value)))
const groups=computed(()=>Object.entries(Object.groupBy(filtered.value,s=>date(s.startsAt))))
async function load(){busy.value=true;error.value='';try{sessions.value=await api(`/sessions?from=${encodeURIComponent(from.value+'T00:00:00+08:00')}&until=${encodeURIComponent(until.value+'T23:59:59+08:00')}`)}catch(e){error.value=e.message}finally{busy.value=false}}
function reset(){category.value='';teacher.value='';location.value='';from.value=today;until.value=new Date(Date.now()+30*86400000).toISOString().slice(0,10);load()}
onMounted(load)
</script>
<template><Hero title="公開課表" subtitle="探索適合你的練習時光"/><section class="container section"><form class="filters" @submit.prevent="load"><label>開始日期<input type="date" v-model="from" required></label><label>結束日期<input type="date" v-model="until" :min="from" required></label><label>課程類型<select v-model="category"><option value="">全部類型</option><option v-for="c in categories" :key="c">{{c}}</option></select></label><label>老師<select v-model="teacher"><option value="">全部老師</option><option v-for="t in teachers" :key="t">{{t}}</option></select></label><label>上課地點<select v-model="location"><option value="">全部地點</option><option v-for="l in locations" :key="l">{{l}}</option></select></label><button class="button" :disabled="busy"><SlidersHorizontal :size="16"/>搜尋</button><button type="button" class="button outline" @click="reset">重設</button></form>
<p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="busy" role="status">讀取課表中…</p><div class="section-heading"><div class="segmented"><button :class="{selected:!calendar}" @click="calendar=false"><List :size="17"/>卡片列表</button><button :class="{selected:calendar}" @click="calendar=true"><CalendarDays :size="17"/>每日課表</button></div><span>共 {{filtered.length}} 堂課程</span></div>
<div :class="{'calendar-grid':calendar}"><section v-for="[day,items] in groups" :key="day" class="day-group"><h3>{{day}}</h3><article v-for="s in items" :key="s.id" class="session-card" :class="{compact:calendar}"><img src="/images/yoga-hero.png" alt="瑜珈練習示意"><div class="session-time">{{time(s.startsAt)}}<span>— {{time(s.endsAt)}}</span></div><div class="session-info"><RouterLink :to="`/courses/${s.courseId}`"><h3>{{s.name}}</h3></RouterLink><span class="badge">{{s.category}}</span><div class="meta"><span><UserRound :size="14"/>{{s.teacher}}</span><span><MapPin :size="14"/>{{s.location}}</span></div></div><div class="session-actions"><span class="badge" :class="{full:s.enrolled>=s.capacity}">{{s.enrolled>=s.capacity?'已額滿':`剩餘 ${s.capacity-s.enrolled} 位`}} · {{s.enrolled}} / {{s.capacity}}</span><div class="actions"><RouterLink class="button small outline" :to="`/courses/${s.courseId}`">查看詳情</RouterLink><RouterLink v-if="s.enrolled<s.capacity && new Date(s.startsAt)>new Date()" class="button small" :to="`/trial?session=${s.id}`">申請體驗</RouterLink></div></div></article></section></div><p v-if="!busy&&!error&&!filtered.length" class="empty">這段時間沒有符合條件的課程，試試其他日期或篩選條件。</p></section></template>
